signature.code:
useField(resource, path): {
  value, error, isChanged, isTouched,
  onChange, onBlur, set, reset, validate
}

examples.code:
function NameField({ resource }) {
  const { value, error, isChanged, onChange, onBlur } = useField(resource, 'name');
  return (
    <label>
      Name {isChanged && <em>(edited)</em>}
      <input
        value={value ?? ''}
        onChange={(e) => onChange(e.target.value)}
        onBlur={onBlur}
        aria-invalid={!!error}
      />
      {error && <span role="alert">{error}</span>}
    </label>
  );
}

function CityField({ resource }) {
  const { value, error, onChange, onBlur } = useField(resource, 'addresses.0.city');
  return (
    <label>
      City
      <input
        value={value ?? ''}
        onChange={(e) => onChange(e.target.value)}
        onBlur={onBlur}
      />
      {error}
    </label>
  );
}

function NotifyField({ resource }) {
  const { value, onChange } = useField(resource, 'notifyEmail');
  return (
    <label>
      <input
        type="checkbox"
        checked={!!value}
        onChange={(e) => onChange(e.target.checked)}
      />
      Email me
    </label>
  );
}

function TierField({ resource }) {
  const { value, onChange, onBlur } = useField(resource, 'plan.tier');
  return (
    <select
      value={value ?? 'free'}
      onChange={(e) => onChange(e.target.value)}
      onBlur={onBlur}
    >
      <option value="free">Free</option>
      <option value="pro">Pro</option>
    </select>
  );
}

function PriceField({ resource }) {
  const { value, error, onChange, onBlur } = useField(resource, 'pricing.basePrice');
  return (
    <input
      type="number"
      value={value ?? ''}
      onChange={(e) => onChange(Number(e.target.value))}
      onBlur={onBlur}
    />
  );
}

// after createResourceHooks(...)
const { value, onChange, onBlur, error, reset } = useField('pricing.basePrice');

// Discard just this field
<button type="button" onClick={() => reset()}>Reset price</button>

const field = useField(resource, 'email');

<input
  value={field.value ?? ''}
  onChange={(e) => field.onChange(e.target.value)}
  onBlur={async () => {
    field.onBlur();
    await field.validate();
  }}
/>
